pub fn checked(self: *Engine, value: c.JSValue) !c.JSValue {
    const result = self.nativeCallbackResult(value);
    if (c.JS_IsException(result)) {
        if (!c.JS_HasException(self.context)) {
            if (c.JS_PiIsExecutionTermination(result)) _ = c.JS_Throw(self.context, result)
            else _ = c.JS_ThrowInternalError(self.context, "Native callback returned exception without a pending reason");
        }
        return self.captureException(self.context);
    }
    return result;
}

pub fn freeValue(self: *Engine, value: c.JSValue) void {
    c.JS_FreeValue(self.context, value);
}

pub fn toString(self: *Engine, value: c.JSValue) ![]u8 {
    var length: usize = 0;
    const bytes = c.JS_ToCStringLen(self.context, &length, value);
    if (bytes == null) {
        return self.captureException(self.context);
    }
    defer c.JS_FreeCString(self.context, bytes);
    return self.gpa.dupe(u8, bytes[0..length]);
}

static JSValue JS_PRINTF_FORMAT_ATTR(5, 0)
JS_MakeError(JSContext *ctx, JSErrorEnum error_num, bool add_backtrace,
             bool *metadata_failed,
             JS_PRINTF_FORMAT const char *fmt, va_list ap)
{
    char buf[256];

    vsnprintf(buf, sizeof(buf), fmt, ap);
    return js_make_error2_tracked(ctx, error_num, add_backtrace, buf, metadata_failed);
}

JS_ThrowError2(JSContext *ctx, JSErrorEnum error_num, bool add_backtrace,
               JS_PRINTF_FORMAT const char *fmt, va_list ap)
{
    JSValue obj;
    bool metadata_failed = false;

    if (ctx->pi_compiler_diagnostic && JS_HasException(ctx))
        return JS_EXCEPTION;
    if (ctx->pi_compiler_diagnostic && error_num == JS_SYNTAX_ERROR)
        return js_pi_compiler_syntax_error(ctx, fmt, ap);
    obj = JS_MakeError(ctx, error_num, add_backtrace, &metadata_failed, fmt, ap);
    if (metadata_failed)
        return js_pi_metadata_fail_owned(ctx, obj);
    if (ctx->pi_link_preparing && (JS_IsException(obj) || JS_HasException(ctx))) {
        JSValue first = JS_HasException(ctx) ? JS_GetException(ctx) : JS_NULL;
        JS_FreeValue(ctx, obj);
        return JS_Throw(ctx, first);
    }
    if (ctx->pi_compiler_diagnostic && (JS_IsException(obj) || JS_HasException(ctx)))
        return js_pi_compiler_fail_owned(ctx, obj);
    if (unlikely(JS_IsException(obj))) {
        /* out of memory: throw JS_NULL to avoid recursing */
        obj = JS_NULL;
    }
    return JS_Throw(ctx, obj);

bool JS_IsError(JSValueConst val)
{
    return JS_CLASS_ERROR == JS_GetClassID(val);
}

/* used to avoid catching interrupt exceptions */
bool JS_IsUncatchableError(JSValueConst val)
{
    JSObject *p;
    if (JS_VALUE_GET_TAG(val) != JS_TAG_OBJECT)
        return false;
    p = JS_VALUE_GET_OBJ(val);
    return p->class_id == JS_CLASS_ERROR && p->is_uncatchable_error;

fn init(self: *Fixture) !void {
    self.* = .{ .native_environment = .init(std.testing.allocator) };
    errdefer self.deinit();
    self.engine = try em.Engine.init(std.testing.allocator, .{});
    self.engine_alive = true;
    try @import("extensions/native_process.zig").install(
        self.engine, std.testing.io, &self.native_environment, &.{"native-reqwrap-routing"});
    const ignored = try a.expression(self.engine, bootstrap, .{self});
    self.engine.freeValue(ignored);
    self.controller = switch (try fs_io.acquire(self.engine, self.env())) {
        .ready => |actual| actual,
        .failed => return error.ActualReqWrapServiceAdmissionFailed,
    };
}
fn bootstrap(s: *a.Scope, self: *Fixture) !c.JSValue {
    const global = try s.checked(c.JS_GetGlobalObject(s.engine.context));
    const process = try s.get(global, "process");
    const generation = try s.beforeAllocation();
    const symbol = try s.checkedAllocation(
        c.JS_NewSymbol(s.engine.context, "node:resource_symbol", false), generation);
    const environment = try callbacks.Environment.create(s.engine, .{
        .provider_names = providers.names(false), .resource_symbol = symbol,
        .process_object = process, .async_context_frame = true, .operations = operations,
    });
    self.environment = environment;
    environment.markBootstrapComplete();
    self.registry_owner = try native.Registry.create(s.engine, environment);
    const object = try s.get(global, "Object");
    self.prototype = a.duplicate(s.engine, try s.get(object, "prototype"));
    self.reason = a.duplicate(s.engine, try s.object());
    return c.pi_js_undefined();
